-- Load the localhost facility list onto the server.
-- Localhost is not modified by this file.
-- Regions loaded: Acholi, Ankole, Bugisu, Bukedi, Bunyoro, Busoga, Kampala,
-- Karamoja, Kigezi, Lango, North Buganda, South Buganda, Teso, Tooro, West Nile.
--
-- On the server:
--   psql -h localhost -U postgres -d fpscore -v ON_ERROR_STOP=1 -f server-adopt-localhost-geography.sql
--
-- Sample health workers and area assignments that point at the old Central /
-- Eastern list are removed so the facilities can be replaced. The load stops
-- if a proficiency assessment or an RH SPARS visit already exists.

BEGIN;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM assessments) OR EXISTS (SELECT 1 FROM rhspars_assessments) THEN
        RAISE EXCEPTION 'This server already has assessments. Geography was not replaced.';
    END IF;
END $$;

DELETE FROM health_workers;
DELETE FROM user_admin_areas;
DELETE FROM facilities;
DELETE FROM subcounties;
DELETE FROM districts;
DELETE FROM regions;
